function getVehiclesByCategory(category) {
    if (category === "all") return VEHICLES_DATA.vehicles;
    return VEHICLES_DATA.vehicles.filter(v => v.category === category);
}

function getUniqueVehicleClasses() {
    const classes = new Set();
    VEHICLES_DATA.vehicles.forEach(v => classes.add(v.class));
    return Array.from(classes).sort();
}